     1→import { createHash } from "crypto";
     2→import { SignJWT } from "jose";
     3→import { verifyToken as verifyTokenJwt, type JwtPayload } from "./jwt";
     4→
     5→const JWT_SECRET = process.env.JWT_SECRET ?? "dev-secret-change-in-production";
     6→const SECRET = new TextEncoder().encode(JWT_SECRET);
     7→const EXPIRES_IN = "7d";
     8→
     9→export type { JwtPayload } from "./jwt";
    10→
    11→/** 密码哈希（SHA-256），用于存储与校验 */
    12→export function hashPassword(password: string): string {
    13→  return createHash("sha256").update(password, "utf8").digest("hex");
    14→}
    15→
    16→export function verifyPassword(plain: string, hash: string): boolean {
    17→  return hashPassword(plain) === hash;
    18→}
    19→
    20→/** 签发 JWT，payload 含 userId、role，默认 7 天过期 */
    21→export async function signToken(payload: JwtPayload): Promise<string> {
    22→  return new SignJWT({ ...payload })
    23→    .setProtectedHeader({ alg: "HS256" })
    24→    .setExpirationTime(EXPIRES_IN)
    25→    .sign(SECRET);
    26→}
    27→
    28→export { verifyToken } from "./jwt";
    29→
    30→import type { NextRequest } from "next/server";
    31→import { cookies } from "next/headers";
    32→
    33→/** 从 cookie 或 Authorization 头取 token（cookie 优先，便于同源请求带 cookie） */
    34→export function getTokenFromRequest(request: NextRequest): string | null {
    35→  const fromCookie = request.cookies.get("token")?.value;
    36→  if (fromCookie) return fromCookie;
    37→  const auth = request.headers.get("authorization");
    38→  return auth?.startsWith("Bearer ") ? auth.slice(7) : null;
    39→}
    40→
    41→/** 在 Server Component 中从 cookie 取 token（用于服务端取数） */
    42→export async function getTokenFromCookies(): Promise<string | null> {
    43→  const store = await cookies();
    44→  return store.get("token")?.value ?? null;
    45→}
    46→
    47→/**
    48→ * Server Component 用：从 cookie 取 token 并校验，返回当前用户身份（userId、role），未登录返回 null。
    49→ * 需要「当前用户」的页面只调这个即可，不用到处写 getTokenFromCookies + verifyToken。
    50→ */
    51→export async function getCurrentUserPayload(): Promise<JwtPayload | null> {
    52→  const token = await getTokenFromCookies();
    53→  return token ? await verifyTokenJwt(token) : null;
    54→}
