1→import { NextResponse } from "next/server";
     2→import type { NextRequest } from "next/server";
     3→import { verifyToken } from "@/lib/jwt";
     4→
     5→const TOKEN_COOKIE = "token";
     6→
     7→/** 仅对页面路由做鉴权与按角色跳转，不处理 /api */
     8→export function middleware(request: NextRequest) {
     9→  const { pathname } = request.nextUrl;
    10→
    11→  const token = request.cookies.get(TOKEN_COOKIE)?.value ?? null;
    12→  const isAdminRoute =
    13→    pathname.startsWith("/dashboard") ||
    14→    pathname.startsWith("/users") ||
    15→    pathname.startsWith("/user");
    16→  const isAppRoute =
    17→    pathname.startsWith("/posts") || pathname.startsWith("/profile");
    18→  const isAuthRoute = pathname === "/login" || pathname === "/register";
    19→
    20→  if (isAuthRoute) {
    21→    return NextResponse.next();
    22→  }
    23→
    24→  if (!token) {
    25→    if (isAdminRoute || isAppRoute) {
    26→      const login = new URL("/login", request.url);
    27→      login.searchParams.set("from", pathname);
    28→      return NextResponse.redirect(login);
    29→    }
    30→    return NextResponse.next();
    31→  }
    32→
    33→  return verifyToken(token).then((payload) => {
    34→    if (!payload) {
    35→      if (isAdminRoute || isAppRoute) {
    36→        const login = new URL("/login", request.url);
    37→        login.searchParams.set("from", pathname);
    38→        const res = NextResponse.redirect(login);
    39→        res.cookies.set(TOKEN_COOKIE, "", { path: "/", maxAge: 0 });
    40→        return res;
    41→      }
    42→      return NextResponse.next();
    43→    }
    44→
    45→    if (isAdminRoute && payload.role !== "admin") {
    46→      return NextResponse.redirect(new URL("/posts", request.url));
    47→    }
    48→
    49→    return NextResponse.next();
    50→  });
    51→}
    52→
    53→export const config = {
    54→  matcher: ["/((?!api|_next/static|_next/image|favicon.ico).*)"],
    55→};
