     1→import { jwtVerify } from "jose";
     2→
     3→/** 仅用 jose，无 Node crypto，供 Edge（middleware）使用 */
     4→const JWT_SECRET = process.env.JWT_SECRET ?? "dev-secret-change-in-production";
     5→const SECRET = new TextEncoder().encode(JWT_SECRET);
     6→
     7→export type JwtPayload = { userId: string; role: string };
     8→
     9→/** 校验并解析 JWT，失败返回 null */
    10→export async function verifyToken(
    11→  token: string
    12→): Promise<JwtPayload | null> {
    13→  try {
    14→    const { payload } = await jwtVerify(token, SECRET);
    15→    const userId = payload.userId as string;
    16→    const role = payload.role as string;
    17→    if (!userId || !role) return null;
    18→    return { userId, role };
    19→  } catch {
    20→    return null;
    21→  }
    22→}
